# -*- coding: utf-8 -*-

import re

from pytest import raises

from blackd import exceptions as ex


def test_blackd_exception():
    exc = ex.BlackdException("Test")
    assert str(exc) == "Test"


def test_blackd_exception_with_args():
    exc = ex.BlackdException("Test", "one", 2, three="four")
    assert str(exc) == "Test one 2 three=four"


def test_blackd_exception_with_format():
    exc = ex.BlackdException("Test {0} {1}", "one", 2)
    assert str(exc) == "Test one 2"

    exc = ex.BlackdException("Test {0} {1}", "one", 2, 3)
    assert str(exc) == "Test one 2 3"

    exc = ex.BlackdException("Test {0} {1}", "one", 2, three="four")
    assert str(exc) == "Test one 2 three=four"


def test_blackd_exception_with_kwargs():
    exc = ex.BlackdException("Test {one} {two}", one="1", two="2")
    assert str(exc) == "Test 1 2"

    exc = ex.BlackdException("Test {one} {two}", one="1", two="2", three="3")
    assert str(exc) == "Test 1 2 three=3"

    exc = ex.BlackdException("Test {one} {two}", one="1", two="2", three="3")
    assert str(exc)
